def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Ensure record data exists
    if not hasattr(self, "_data") or self._data is None:
        raise ValueError("Record has no data to return")

    # Resolve the list of keys in order
    try:
        key_list = list(self._data.keys())
    except Exception as exc:
        raise ValueError("Unable to obtain keys from record data") from exc

    # If no specific keys are requested, return all
    if not keys:
        return dict(self._data)

    result = {}
    for k in keys:
        # Handle index-based key selection
        if isinstance(k, int):
            try:
                key_name = key_list[k]
            except IndexError as exc:
                raise IndexError(f"Index {k} is out of bounds") from exc
            result[key_name] = self._data.get(key_name)
        # Handle string-based key selection
        elif isinstance(k, str):
            key_name = k
            result[key_name] = self._data.get(key_name, None)
        else:
            raise TypeError(f"Key {k!r} is neither an integer index nor a string field name")
    return result

