def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    from functools import wraps

    # Handle cases where the cache size is non-positive
    if maxsize <= 0:
        def decorator(func):
            return func
        return decorator

    # Helper to create a hashable key from arguments
    def make_key(args, kwargs, typed):
        key = args
        if kwargs:
            sorted_items = tuple(sorted(kwargs.items()))
            key += sorted_items
        if typed:
            key += tuple(type(v) for v in args)
            if kwargs:
                key += tuple(type(v) for _, v in sorted_items)
        return key

    def decorator(func):
        cache = {}
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs, typed)
            if key in cache:
                # Move to end to mark as most recently used
                value = cache.pop(key)
                cache[key] = value
                return value
            value = func(*args, **kwargs)
            if len(cache) >= maxsize:
                # Evict the most recently used item (the last entry)
                cache.popitem(last=True)
            cache[key] = value
            return value
        return wrapper
    return decorator

