def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    # Ensure maxsize is a positive integer
    try:
        maxsize = int(maxsize)
        if maxsize <= 0:
            # No caching if non-positive maxsize
            return lambda func: func
    except Exception:
        # If maxsize is invalid, fallback to default
        maxsize = 128

    def decorator(func):
        from collections import OrderedDict
        from functools import wraps
        import threading

        cache = OrderedDict()
        lock = threading.Lock()

        def _make_key(args, kwargs, typed_flag):
            """Create a hashable key for the cache based on args and kwargs."""
            try:
                # Base key from positional arguments
                key = args
                # Include keyword arguments sorted by key name
                if kwargs:
                    key += tuple(sorted(kwargs.items()))
                # Include types if typed flag is True
                if typed_flag:
                    key += tuple(type(a) for a in args)
                    if kwargs:
                        key += tuple(type(v) for _, v in sorted(kwargs.items()))
                return key
            except Exception:
                # If any component is not hashable, signal by raising
                raise ValueError("Unhashable arguments")

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Attempt to build cache key
            try:
                key = _make_key(args, kwargs, typed)
            except Exception:
                # Cannot hash key; skip caching
                return func(*args, **kwargs)

            with lock:
                # If key is in cache, move it to the end (most recently used)
                if key in cache:
                    cache.move_to_end(key)
                    return cache[key]
                # Compute the function result
                result = func(*args, **kwargs)
                # Add to cache
                cache[key] = result
                # If cache exceeds maxsize, remove the oldest item
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                return result

        return wrapper

    return decorator

