def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    # Try to use the cached ``__provides__`` attribute if it exists
    try:
        decl = getattr(object, "__provides__", None)
        if decl is not None:
            return decl
    except Exception:
        # If accessing ``__provides__`` raises an error, fall back to computing
        pass

    # Determine the type to inspect (the object itself if it is a class,
    # otherwise its type)
    try:
        cls = object if isinstance(object, type) else type(object)
    except Exception:
        cls = type(object)

    # Collect the interfaces directly declared on the class hierarchy.
    # ``__provides__`` can be a single interface, a list, or a set.
    directly = set()
    for base in cls.__mro__:
        if hasattr(base, "__provides__"):
            value = getattr(base, "__provides__", None)
            if isinstance(value, (list, tuple, set)):
                directly.update(value)
            elif value is not None:
                directly.add(value)

    return directly

