def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of classes")
    result = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"'{cls}' is not a class")
        # skip if cls is a superclass of any other class in the list
        if any(issubclass(other, cls) and other is not cls for other in classes):
            continue
        if cls not in result:
            result.append(cls)
    return result

