def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    import inspect

    result = []
    cls = self.__class__

    for name, obj in inspect.getmembers(cls):
        # Skip private and special members
        if name.startswith('_'):
            continue

        # If not requesting all, omit callable members (like methods)
        if not all and callable(obj):
            continue

        # Prefer property docstring, otherwise fall back to the object's __doc__
        if isinstance(obj, property):
            desc = obj.__doc__
        else:
            desc = getattr(obj, '__doc__', None)

        # Ensure a string is always returned
        if desc is None:
            desc = ""

        result.append((name, desc))

    # Return a sorted list for deterministic order
    return sorted(result, key=lambda pair: pair[0])

