    """Return the attribute names defined by the interface."""
    # When `all` is True, return all non-private attributes of the instance.
    if all:
        return sorted([name for name in dir(self) if not name.startswith('_')])

    # Otherwise, return attributes that are part of the class interface
    # (immediate class attributes that are not methods or private).
    names = []
    for name, attr in vars(self.__class__).items():
        if name.startswith('_'):
