        # Include properties as they are part of the interface
        if isinstance(attr, property):
            names.append(name)
        # Include any non-callable, non-method class attributes
        elif not callable(attr) and not isinstance(attr, (staticmethod, classmethod)):
            names.append(name)

    return sorted(names)

