def reset(self):
    '''Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    '''
    # Reset context
    try:
        self.context = {}
    except Exception:
        # If no context attribute exists, ignore
        pass

    # Reinitialize bins
    try:
        # If an explicit initial value is provided, fill bins with it
        if hasattr(self, 'initial_value'):
            # Determine number of bins
            bin_count = getattr(self, 'n_bins', None)
            if bin_count is None:
                # Fallback: use current bin count if available
                current_bins = getattr(self, 'bins', [])
                bin_count = len(current_bins)
            self.bins = [self.initial_value] * bin_count
        # Otherwise try to create new bins using make_bins()
        elif hasattr(self, 'make_bins'):
            self.bins = self.make_bins()
        else:
            # If neither is available, clear bins to an empty list
            self.bins = []
    except Exception as exc:
        raise RuntimeError(f'Failed to reset histogram bins: {exc}') from exc

