def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    lines = []
    if header is not None:
        lines.append(str(header))

    # Try to iterate over (point, value) pairs. Fall back to different patterns.
    iterator = None
    try:
        iterator = iter(self.items())
    except AttributeError:
        try:
            iterator = iter(self)
        except TypeError:
            # If iterating over a plain iterable of (point, value) tuples.
            iterator = iter(self)

    for entry in iterator:
        # Handle possible (point, value) tuple
        if isinstance(entry, tuple) and len(entry) == 2:
            point, value = entry
        else:
            # Skip malformed entries
            continue

        # Convert point (coordinate) to string
        if isinstance(point, (list, tuple, set)) and not isinstance(point, (str, bytes)):
            coord_str = separator.join(map(str, point))
        else:
            coord_str = str(point)

        # Convert value to parts; if iterable, expand, otherwise single part
        if isinstance(value, (list, tuple, set)) and not isinstance(value, (str, bytes)):
            value_parts = [str(v) for v in value]
        else:
            value_parts = [str(value)]

        line = separator.join([coord_str] + value_parts)
        lines.append(line)

    return "\n".join(lines)

