def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate.

    The method looks for an error array associated with ``coord_name`` in
    ``self._errors`` (a dict) or ``self.errors`` (an alternative attribute).
    It returns the indices where the error values are finite and non‑zero.
    If no error information is available the method raises a helpful error.

    Returns
    -------
    np.ndarray
        1‑D array of integer indices where the error values are finite and
        non‑zero.  An empty array is returned if no such indices exist.
    """
    import numpy as np

    # Try to find the error container
    err_container = None
    if hasattr(self, "_errors"):
        err_container = getattr(self, "_errors")
    elif hasattr(self, "errors"):
        err_container = getattr(self, "errors")

    if err_container is None:
        raise AttributeError(
            "The object does not have an '_errors' or 'errors' attribute "
            "from which to retrieve error indices."
        )

    # Retrieve the error array for the specified coordinate
    try:
        if isinstance(err_container, dict):
            if coord_name not in err_container:
                raise KeyError(
                    f"No error array found for coordinate '{coord_name}'."
                )
            err_arr = err_container[coord_name]
        else:
            # Assume the container is already the error array itself
            err_arr = err_container
    except Exception as exc:
        raise ValueError(
            f"Failed to extract error data for '{coord_name}': {exc}"
        ) from exc

    try:
        err_arr = np.asarray(err_arr)
    except Exception as exc:
        raise TypeError(
            f"Error data for coordinate '{coord_name}' could not be "
            f"converted to a NumPy array: {exc}"
        ) from exc

    if err_arr.ndim == 0:
        # Scalar error – no indices to return
        return np.empty(0, dtype=int)

    # Determine indices where the error is finite and non‑zero
    mask = np.isfinite(err_arr) & (err_arr != 0)
    return np.where(mask)[0] if mask.any() else np.empty(0, dtype=int)

