def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Convert coord to a numpy array for consistency
    try:
        coord_arr = np.asarray(coord, dtype=float)
    except Exception as exc:
        raise ValueError(f"Coordinate must be array-like or scalar, got {coord!r}") from exc

    # Determine dimensionality
    if hasattr(self, 'ndim'):
        n_dims = self.ndim
    else:
        n_dims = self.values.ndim
    # Handle 1‑D case where coord is a scalar
    if coord_arr.ndim == 0:
        coord_arr = coord_arr.reshape((1,))
    elif coord_arr.ndim != 1:
        raise ValueError(f"coord must be a 1‑D array-like, got shape {coord_arr.shape}")

    if len(coord_arr) != n_dims:
        raise ValueError(f"coord length {len(coord_arr)} does not match histogram dimensionality {n_dims}")

    # Validate weight
    try:
        w = float(weight)
    except Exception as exc:
        raise ValueError(f"weight must be numeric, got {weight!r}") from exc

    # Compute bin indices for each dimension
    indices = []
    for dim in range(n_dims):
        edges = self.edges[dim]
        if not hasattr(edges, '__len__') or len(edges) < 2:
            raise ValueError(f"Histogram edges for dimension {dim} are invalid: {edges!r}")

        # searchsorted gives index where to insert to keep order
        idx = np.searchsorted(edges, coord_arr[dim], side='right') - 1
        # Check if index is out of bounds
        if idx < 0 or idx >= len(edges) - 1:
            # coordinate outside histogram bounds – ignore
            return
        indices.append(idx)

    # Update the bin value (handle potential broadcasting with weight)
    try:
        self.values[tuple(indices)] += w
    except Exception as exc:
        raise RuntimeError(f"Failed to update histogram bin at indices {indices}: {exc}") from exc
    return None

