def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    messages = []
    import re

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            messages.append({repr(key): 'expected string or bytes-like object'})
        else:
            # Convert bytes to str for regex matching
            key_str = key.decode() if isinstance(key, bytes) else key
            try:
                if not LABEL_KEY_REGEX.match(key_str):
                    messages.append({repr(key): f"Label key '{key_str}' does not match the regex [...]"})
            except NameError:
                # If the regex constant is not defined, ignore regex check
                pass

        # Helper to validate value(s)
        def _validate_value(val, origin):
            if isinstance(val, (list, tuple)):
                for item in val:
                    _validate_value(item, origin)
            else:
                if not isinstance(val, (str, bytes)):
                    messages.append({repr(val): 'expected string or bytes-like object'})
                else:
                    val_str = val.decode() if isinstance(val, bytes) else val
                    try:
                        if not LABEL_VALUE_REGEX.match(val_str):
                            messages.append({repr(val): f"Label value '{val_str}' does not match the regex [...]"})
                    except NameError:
                        pass

        _validate_value(value, key)

    if messages:
        raise ValidationError(messages)

