def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or
    ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dict")

    result = {}
    # Helper to process nested dicts
    def _process(value, level):
        if isinstance(value, dict):
            return generate_default_observer_schema_dict(value, first_level=False)
        if isinstance(value, list):
            return [
                _process(v, level) if isinstance(v, (dict, list)) else None
                for v in value
            ]
        # Primitive value
        return None

    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            if key == "metadata" and isinstance(value, dict):
                # Preserve identifying fields inside metadata
                metadata_res = {}
                for mkey, mvalue in value.items():
                    if isinstance(mvalue, dict):
                        metadata_res[mkey] = _process(mvalue, first_level=False)
                    elif isinstance(mvalue, list):
                        metadata_res[mkey] = [
                            _process(v, False) if isinstance(v, (dict, list)) else None
                            for v in mvalue
                        ]
                    else:
                        if first_level and mkey in ("name", "namespace"):
                            metadata_res[mkey] = mvalue
                        else:
                            metadata_res[mkey] = None
                result[key] = metadata_res
            else:
                result[key] = _process(value, False)
        elif isinstance(value, list):
            result[key] = [ _process(v, False) if isinstance(v, (dict, list)) else None
                            for v in value ]
        else:
            if first_level and key in ("apiVersion", "kind"):
                result[key] = value
            else:
                result[key] = None
    return result

