    # Defensive checks for input types
    if last_applied_manifest is None:
        last_applied_manifest = []
    if response is None:
        response = []

    if not isinstance(last_applied_manifest, list):
        raise TypeError(
            f"last_applied_manifest must be a list, got {type(last_applied_manifest)!r}"
        )
    if not isinstance(observer_schema, list):
        raise TypeError(
            f"observer_schema must be a list, got {type(observer_schema)!r}"
        )
    if not isinstance(response, list):
        raise TypeError(
            f"response must be a list, got {type(response)!r}"
        )

    # Ensure the list is long enough to hold all response items
    if len(last_applied_manifest) < len(response):
        # Append empty dicts for new entries
        for _ in range(len(response) - len(last_applied_manifest)):
            last_applied_manifest.append({})

    # Iterate over response entries
    for idx, resp_item in enumerate(response):
        # Ensure we have a dict placeholder for the current index
        curr = last_applied_manifest[idx]
        if not isinstance(curr, dict):
            curr = {}
            last_applied_manifest[idx] = curr

        # If the response item is a dict, initialise missing fields
        if isinstance(resp_item, dict):
            for field in observer_schema:
                if field not in curr:
                    # Use the value from the response if present, otherwise None
                    curr[field] = resp_item.get(field, None)
        # If the response item is not a dict, just copy it if it's missing
        else:
            if idx >= len(last_applied_manifest):
                last_applied_manifest.append(resp_item)

    # Truncate any extra items that may have been present originally
    if len(last_applied_manifest) > len(response):
        del

