def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Conveniently exit if the structure is not present
    if not hasattr(app, "spec") or not hasattr(app.spec, "manifest"):
        return

    try:
        manifest = app.spec.manifest
    except Exception:
        # If we cannot read manifest, abort silently
        return

    # Iterate over all resources in the application manifest
    for name, resource in manifest.items():
        # Skip None entries
        if resource is None:
            continue

        # Determine if a custom observer schema already exists
        has_custom_schema = False
        try:
            # Use different attribute names in case custom schema is stored on the
            # object or inside the dict representation
            if hasattr(resource, "observer_schema"):
                has_custom_schema = bool(resource.observer_schema)
            elif isinstance(resource, dict):
                has_custom_schema = bool(resource.get("observer_schema"))
        except Exception:
            # If attribute access fails, consider that there is no custom schema
            has_custom_schema = False

        if has_custom_schema:
            # Skip resources that already have a custom schema
            continue

        # Build a very simple default schema
        default_schema = {"type": "object", "description": f"Default observer schema for {name}"}

        # Try to add a placeholder for properties based on the resource's keys
        if isinstance(resource, dict):
            # For a dict-based resource simply expose all keys as strings
            default_schema["properties"] = {k: {"type": "string"} for k in resource.keys()}
        else:
            # If the resource supports conversion to a dict (e.g., via to_dict),
            # try to use its keys; otherwise leave properties empty.
            try:
                if hasattr(resource, "to_dict") and callable(resource.to_dict):
                    props = resource.to_dict().keys()
                    default_schema["properties"] = {k: {"type": "string"} for k in props}
                else:
                    default_schema["properties"] = {}
            except Exception:
                default_schema["properties"] = {}

        # Inject the default schema back into the resource
        try:
            if hasattr(resource, "observer_schema"):
                resource.observer_schema = default_schema
            elif isinstance(resource, dict):
                resource["observer_schema"] = default_schema
        except Exception:
            # Skip if we cannot set the schema
