def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in
    later versions than the version being described.
    """
    # Check that the requested version is in the inventory
    if version not in inventory:
        raise ValueError(f"Version '{version}' not found in inventory")

    # Helper to determine version order; try to use LooseVersion if available
    try:
        from distutils.version import LooseVersion
        sorted_versions = sorted(inventory.keys(), key=lambda v: LooseVersion(v))
    except Exception:
        # Fallback to simple string sorting
        sorted_versions = sorted(inventory.keys())

    # Find the position of the requested version in the sorted list
    try:
        start_index = sorted_versions.index(version)
    except ValueError:
        # Should not happen because we checked membership above
        start_index = 0

    # Start with an empty map
    path_map = {}

    # Iterate over the requested version and all later versions
    for v in sorted_versions[start_index:]:
        mapping = inventory[v]

        # Support mapping being a dict or an iterable of (logical_path, content_file)
        if isinstance(mapping, dict):
            items = mapping.items()
        else:
            try:
                items = list(mapping)
            except Exception:
                # If mapping is not iterable, skip
                continue

        for logical, content in items:
            # Ensure we treat content as a single filename, even if a list/tuple is provided
            if isinstance(content, (list, tuple)):
                for c in content:
                    path_map.setdefault(logical, set()).add(c)
            else:
                path_map.setdefault(logical, set()).add(content)

    return path_map

