def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if not hasattr(manifest_files, "__iter__"):
        raise ValueError("manifest_files must be an iterable")

    # The fixity block is expected to contain a 'files' key with a list of file names
    files = fixity.get("files")
    if files is None:
        raise ValueError("Missing 'files' key in fixity block")

    if not isinstance(files, list):
        raise ValueError("'files' entry must be a list")

    # Collect the set of file names that are actually present in the manifest
    manifest_set = set()
    for entry in manifest_files:
        if isinstance(entry, str):
            manifest_set.add(entry)

    # Check that every referenced file exists in the manifest
    missing = [f for f in files if f not in manifest_set]
    if missing:
        raise ValueError(
            f"Fixity block references files not present in the manifest: {missing}"
        )

    # Optionally, ensure that the block does not contain unexpected keys
    # (Allow common keys that might appear in a fixity block)
    allowed_keys = {"type", "algorithm", "value", "files", "path", "size"}
    unexpected_keys = set(fixity) - allowed_keys
    if unexpected_keys:
        raise ValueError(
            f"Unexpected keys in fixity block: {sorted(unexpected_keys)}"
        )

