def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    # Validate input
    if not isinstance(folder, str):
        raise TypeError("folder must be a str path")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"The specified folder does not exist: {folder}")

    package_files = {}
    try:
        # First pass: find all .xml files and initialize groups
        for root, _, files in os.walk(folder):
            for fname in files:
                base, ext = os.path.splitext(fname)
                if ext.lower() == ".xml":
                    full_path = os.path.join(root, fname)
                    package_files.setdefault(base, []).append(full_path)

        # Second pass: add non-xml files that share the base name
        for root, _, files in os.walk(folder):
            for fname in files:
                base, ext = os.path.splitext(fname)
                if base in package_files and ext.lower() != ".xml":
                    full_path = os.path.join(root, fname)
                    package_files[base].append(full_path)

    except OSError as exc:
        # If reading the directory fails, log and return empty dict
        try:
            import logging
            logging.getLogger(__name__).warning("Failed to explore folder %s: %s", folder, exc)
        except Exception:
            pass
        return {}

    return package_files

