def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string")

    import os
    import zipfile

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"Zip file does not exist: {zip_path}")

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for info in zf.infolist():
                # Skip directories
                if info.is_dir():
                    continue

                filename = info.filename
                # Determine the base name without extension
                base = os.path.splitext(os.path.basename(filename))[0]

                # Initialize dictionary for this base if needed
                if base not in packages:
                    packages[base] = {}

                # Read the content of the file
                try:
                    content = zf.read(info)
                except KeyError:
                    # File disappeared between infolist and read
                    continue

                packages[base][filename] = content
    except zipfile.BadZipFile as e:
        raise RuntimeError(f"Invalid zip file '{zip_path}': {e}") from e
    except Exception as e:
        raise RuntimeError(f"Error processing zip file '{zip_path}': {e}") from e

    return packages

