def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = '  '

    def _format(obj, level):
        # Handle recursive objects by limiting depth
        max_depth = 10
        if level > max_depth:
            return '…'

        # Debug info
        dbg = f" <{type(obj).__name__}@{id(obj):#x}>" if debug else ""

        if isinstance(obj, dict):
            if not obj:
                return f"{{}}{dbg}"
            items = []
            for key in sorted(obj, key=lambda x: str(x)):
                items.append(f"{' ' * ((level + 1) * len(indent_str))}{repr(key)}: {_format(obj[key], level + 1)}")
            return f"{{{dbg}\n{'\n'.join(items)}\n{' ' * (level * len(indent_str))}}}"
        elif isinstance(obj, (list, tuple, set, frozenset)):
            type_name = type(obj).__name__
            if not obj:
                return f"{type_name}({}){dbg}"
            items = []
            for item in obj:
                items.append(f"{' ' * ((level + 1) * len(indent_str))}{_format(item, level + 1)}")
            sep = ',' if isinstance(obj, (set, frozenset)) else ','
            closing = '}' if isinstance(obj, set) else ')'
            opening = '{' if isinstance(obj, set) else '('
            return f"{type_name}{opening}{dbg}\n{',' .join(items)}{closing}"
        elif isinstance(obj, (str, int, float, bool, type(None))):
            return f"{repr(obj)}{dbg}"
        else:
            # Fallback to repr of the object
            return f"{repr(obj)}{dbg}"

    try:
        return _format(self, indent)
    except Exception as exc:
        # Fallback if something goes wrong
        return f"<pretty failed: {exc}>"

