def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Python 3.8+ standard library
        from importlib.metadata import distributions  # pragma: no cover
    except Exception:
        # Fallback to pkg_resources if importlib.metadata not available
        try:
            import pkg_resources  # pragma: no cover
        except Exception:
            # If neither is available, return a default placeholder
            return {"error": "cannot retrieve package metadata"}
        # Use pkg_resources to get working set of installed distributions
        return {
            dist.project_name: getattr(dist, "version", "unknown")
            for dist in pkg_resources.working_set
        }

    try:
        # Retrieve all distributions and build a mapping of name -> version
        versions = {
            dist.metadata.get("Name") or dist.metadata.get("Package-Name", "unknown"): dist.version
            for dist in distributions()
            if dist.metadata.get("Name") or dist.metadata.get("Package-Name")
        }
        # Normalize: if any version is empty, replace with 'unknown'
        for key, value in list(versions.items()):
            if not value:
                versions[key] = "unknown"
        return versions
    except Exception:
        # Any failure will trigger the fallback to pkg_resources
        try:
            import pkg_resources  # pragma: no cover
        except Exception:
            return {"error": "failed to load package metadata"}
        return {
            dist.project_name: getattr(dist, "version", "unknown")
            for dist in pkg_resources.working_set
        }

