def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    # Validate input types
    if not isinstance(commands, (str, list)):
        raise ValueError("commands must be a string or a list of strings")
    if not isinstance(args, list) or not all(isinstance(a, str) for a in args):
        raise ValueError("args must be a list of strings")

    # Build the full command list
    if isinstance(commands, str):
        cmd_list = [commands] + args
    else:
        if any(not isinstance(c, str) for c in commands):
            raise ValueError("all elements in commands list must be strings")
        cmd_list = commands[:] + args

    # Prepare environment
    env_dict = os.environ.copy() if env else None
    if env:
        if not isinstance(env, dict):
            raise ValueError("env must be a mapping if provided")
        env_dict.update(env)

    # Verbose output
    if verbose:
        print("Running command:", " ".join(cmd_list))

    # Set stderr handling
    stderr_setting = subprocess.PIPE if hide_stderr else None

    try:
        result = subprocess.run(
            cmd_list,
            cwd=cwd,
            env=env_dict,
            stdout=subprocess.PIPE,
            stderr=stderr_setting,
            check=True,
            text=True,
        )
        return result.stdout
    except subprocess.CalledProcessError as e:
        # If stderr is hidden, don't include it in the error message
        err_msg = e.stderr if not hide_stderr and e.stderr else ""
        msg = (
            f"Command '{' '.join(cmd_list)}' failed with return code {e.returncode}"
            + (f"\nError output:\n{err_msg}" if err_msg else "")
        )
        raise RuntimeError(msg) from e
    except OSError as e:
        raise RuntimeError(
            f"Failed to execute command '{' '.join(cmd_list)}': {e}"
        ) from e

