def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""
    try:
        parts = version.split(".")
        new_parts = list(parts)
        # Find the last numeric component
        idx = len(parts) - 1
        while idx >= 0:
            num_str = parts[idx]
            try:
                num = int(num_str)
            except ValueError:
                idx -= 1
                continue
            num += 1
            pad_len = len(num_str)
            new_num_str = str(num)
            if pad_len > len(new_num_str):
                new_num_str = new_num_str.rjust(pad_len, "0")
            new_parts[idx] = new_num_str
            break
        else:
            # No numeric part found; return original
            return version
        return ".".join(new_parts)
    except Exception:
        # In case of any unexpected error, return original string
        return version

