def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        raise ValueError("No version directories supplied for validation")

    # Ensure a root inventory is available for comparison
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise AttributeError("Instance missing a 'root_inventory' dict for comparison")

    # This will hold any digest differences between version inventories
    # and the root inventory; structure:
    # {content_name: [(version_dir, root_digest, version_digest), ...]}
    self.difference_records = {}

    # Keep track of the accumulated inventory seen so far
    accumulated = {}

    import os
    import json  # imports are assumed to be available in the module context

    for vdir in version_dirs:
        inventory_path = os.path.join(vdir, "inventory.json")
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Missing inventory at '{inventory_path}'")
        try:
            with open(inventory_path, "r", encoding="utf-8") as fh:
                current_inventory = json.load(fh)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory from '{inventory_path}': {exc}")

        if not isinstance(current_inventory, dict):
            raise ValueError(f"Inventory in '{inventory_path}' must be a JSON object")

        # 1. Ensure this version contains all entries that have appeared previously
        missing = set(accumulated.keys()) - set(current_inventory.keys())
        if missing:
            raise ValueError(
                f"Inventory in '{inventory_path}' missing entries that existed in earlier versions: "
