def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Validate params argument
    if not isinstance(params, dict):
        raise TypeError(f"params must be a dict, got {type(params).__name__}")
    # Nothing to amend if bug_ids is falsy
    if not bug_ids:
        return params
    # Normalise bug_ids to a list of integers
    bug_id_list = []
    # Helper to convert a single id to int
    def _conv_id(x):
        if isinstance(x, int):
            return x
        if isinstance(x, str):
            x = x.strip()
            if not x:
                raise ValueError("empty bug id string")
            return int(x)
        raise TypeError(f"bug id must be int or str, got {type(x).__name__}")
    # Process the input
    try:
        if isinstance(bug_ids, (int, str)):
            bug_id_list.append(_conv_id(bug_ids))
        elif isinstance(bug_ids, (list, tuple, set)):
            for bid in bug_ids:
                bug_id_list.append(_conv_id(bid))
        else:
            raise TypeError(f"bug_ids must be int, str, list, tuple or set, got {type(bug_ids).__name__}")
    except (ValueError, TypeError) as exc:
        raise ValueError(f"Invalid bug_ids value: {exc}") from exc
    # Remove duplicates while preserving order
    seen = set()
    deduped_ids = []
    for bid in bug_id_list:
        if bid not in seen:
            seen.add(bid)
            deduped_ids.append(bid)
    # Merge with existing 'ids' in params if present
    existing = params.get("ids", None)
    if existing:
        # existing could be a comma separated string or a list
        if isinstance(existing, str):
            existing_ids = [int(x) for x in existing.split(",") if x.strip()]
        elif isinstance(existing, (list, tuple)):
            existing_ids = [int(x) for x in existing]
        else:
            raise TypeError(f"params['ids'] must be str or list, got {type(existing).__name__}")
        merged = list(dict.fromkeys(existing_ids + deduped_ids))
        params["ids"] = ",".join(str(x) for x in merged)
    else:
        params["ids"] = ",".join(str(x) for x in deduped_ids)
    return params

