def bash_completion():
    '''
    Return a bash completion script for the borgmatic command.
    Produce this by introspecting borgmatic's command-line argument parsers.
    '''
    import subprocess
    try:
        import click
    except Exception as e:
        return f"# Error: click not installed: {e}\n"
    try:
        # borgmatic defines its CLI in borgmatic.__main__
        from borgmatic.__main__ import main as borg_main
        root_cmd = borg_main
    except Exception as e:
        return f"# Error: could not import borgmatic command: {e}\n"
    try:
        # click.shell_completion.install_completer returns a string if shell is specified
        script = click.shell_completion.install_completer(root_cmd, 'bash')
        if not script:
            script = f"# Error: click could not generate completion script for {root_cmd.name}\n"
        return script
    except Exception as e:
        return f"# Error: could not generate completion script: {e}\n"

