def parse_arguments(*unparsed_arguments):
    """Parse command-line arguments for a script that may contain subparsers.

    Returns a dictionary mapping from subparser name (or "global") to the
    corresponding ``argparse.Namespace``. The function gracefully handles
    cases where no subparser is used or where a subparser fails to parse
    its arguments.
    """
    parser = argparse.ArgumentParser()
    # Create the subparsers object; actual subparsers may be added
    # later by the caller before calling this function.
    subparsers = parser.add_subparsers(dest="subparser")
    # Parse the known part of the arguments.
    try:
        known, remaining = parser.parse_known_args(unparsed_arguments)
    except Exception as exc:
        # If parsing fails, return only the global namespace with an error attribute.
        namespace = argparse.Namespace(error=str(exc))
        return {"global": namespace}
    result = {"global": known}
    subparser_name = getattr(known, "subparser", None)
    if subparser_name:
        # Attempt to retrieve the parser for the chosen subparser and parse the rest.
        try:
            sub_parser = parser._subparsers._name_parser_map[subparser_name]
            sub_namespace = sub_parser.parse_args(remaining)
            result[subparser_name] = sub_namespace
        except Exception:
            # If subparser parsing fails, store None for that subparser.
            result[subparser_name] = None
    return result

