    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        return {}

    # Allow a single dict to be passed directly (not as an iterable of dicts)
    if isinstance(dicts, dict):
        dicts = [dicts]

    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("`dicts` must be an iterable of dictionaries")

    result = {}
    for d in iterator:
        if d is None:
            continue
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value for key '{key}' must be numeric, got {type(value).__name__}")
            result[key] = result.get(key, 0) + value

    return result

