def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        return url
    if not isinstance(url_args, dict):
        return url

    def _replace(match: re.Match) -> str:
        key = match.group(1)
        # Use the value from args if present, otherwise keep the original placeholder
        return str(url_args.get(key, match.group(0)))

    # Replace {placeholder} patterns
    replaced = re.sub(r'\{([a-zA-Z0-9_]+)\}', _replace, url)
    # Additionally replace :placeholder patterns commonly used in some routing schemes
    replaced = re.sub(r':([a-zA-Z0-9_]+)', _replace, replaced)

    return replaced

