def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Directly treat actual None as "none"
    if val is None:
        return True
    try:
        s = str(val).strip()
    except Exception:
        # If conversion fails, assume it's not a None string
        return False
    # Empty string is considered None
    if not s:
        return True
    # Common textual representations of None
    return s.lower() in ("none", "null", "nil")

