def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    try:
        base = len(alphabet)
    except Exception as exc:
        raise ValueError("alphabet must be a sequence") from exc
    if base < 2:
        raise ValueError("alphabet must contain at least two distinct symbols")
    if len(set(alphabet)) != base:
        raise ValueError("alphabet symbols must be unique")
    if padding is not None and padding < 0:
        raise ValueError("padding must be None or a non-negative integer")
    if not isinstance(number, int):
        raise TypeError("number must be an integer")

    negative = number < 0
    number = abs(number)

    # Special case for zero
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while number:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])

    # The most significant digit should be first
    result = ''.join(reversed(digits))

    if padding is not None:
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result

    if negative:
        result = '-' + result

    return result

