def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    :return: A new dictionary with the specified key replaced by the register number
    """
    def _recursively_replace(item):
        if isinstance(item, dict):
            new_dict = {}
            for k, v in item.items():
                new_key = register_number if k == register_value else k
                new_dict[new_key] = _recursively_replace(v)
            return new_dict
        # If the item is a list, process each element
        if isinstance(item, list):
            return [_recursively_replace(sub_item) for sub_item in item]
        # Base case: return the item unchanged
        return item

    try:
        return _recursively_replace(flow_params)
    except Exception as exc:  # pragma: no cover
        raise ValueError(f"Error while replacing register key: {exc}") from exc

