def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError("Expected a class type, got %r" % cls)
    seen = set()
    stack = [cls]
    while stack:
        c = stack.pop()
        if c not in seen:
            seen.add(c)
            stack.extend(c.__subclasses__())
    seen.discard(cls)
    return seen

