def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Validate input types
    if not isinstance(url, str):
        raise TypeError(f"url must be a str, got {type(url).__name__}")
    if not isinstance(destination_path, Path):
        raise TypeError(f"destination_path must be a pathlib.Path, got {type(destination_path).__name__}")

    # Ensure destination_path exists and is a directory
    try:
        if destination_path.exists():
            if not destination_path.is_dir():
                raise RuntimeError(f"Destination path {destination_path} exists and is not a directory")
        else:
            destination_path.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise RuntimeError(f"Error ensuring destination directory: {exc}") from exc

    # Prepare temporary file for download
    temp_file = None
    try:
        with tempfile.NamedTemporaryFile(delete=False, suffix=".tar.gz") as tmp:
            temp_file = Path(tmp.name)
            # Stream download to avoid memory overhead
            with requests.get(url, stream=True, timeout=30) as response:
                response.raise_for_status()
                for chunk in response.iter_content(chunk_size=8192):
                    if chunk:  # filter out keep-alive chunks
                        tmp.write(chunk)
        # Extract the tar.gz archive
        try:
            with tarfile.open(temp_file, "r:gz") as tar:
                tar.extractall(path=str(destination_path))
        except tarfile.TarError as tre:
            raise RuntimeError(f"Failed to extract tar archive: {tre}") from tre
    except requests.RequestException as re:
        raise RuntimeError(f"Failed to download archive from {url}: {re}") from re
    except Exception as exc:
        raise RuntimeError(f"An unexpected error occurred: {exc}") from exc
    finally:
        # Clean up the temporary file if it exists
        if temp_file and temp_file.exists():
            try:
                temp_file.unlink()
            except Exception:
                pass

    return destination_path

