def unquote(name):
    """Remove outer quotation marks from the given name."""
    if not isinstance(name, (str, bytes)):
        raise TypeError("name must be a string or bytes")
    try:
        s = name.decode() if isinstance(name, bytes) else name
    except Exception:
        s = str(name)

    # Handle single or double quotes
    m = re.match(r"^(?P<q>['\"])(?P<content>.*)(?P=q)$", s, re.S)
    if m:
        content = m.group('content')
        # Unescape escaped quotes and backslashes
        return content.replace(r'\"', '"').replace(r"\'", "'").replace(r"\\", "\\")

    # Handle backticks
    m = re.match(r"^`(?P<content>.*)`$", s, re.S)
    if m:
        return m.group('content')

    # Handle angle brackets <...>
    m = re.match(r"^<(?P<content>.+)>$", s, re.S)
    if m:
        return m.group('content')

    return s

