def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import shutil
    import uuid
    from pathlib import Path

    # Verify the archive exists
    if not os.path.isfile(archive_path):
        raise FileNotFoundError(f"Archive not found: {archive_path}")

    # Ensure the temporary base path exists
    base_tmp = Path(tmp_path)
    base_tmp.mkdir(parents=True, exist_ok=True)

    # Create a unique temporary directory for the extraction
    tmp_dir = base_tmp / f"repo_{uuid.uuid4().hex}"
    try:
        tmp_dir.mkdir(parents=True, exist_ok=False)
    except FileExistsError:
        raise RuntimeError(f"Temporary directory already exists: {tmp_dir}")

    # Extract the archive
    try:
        shutil.unpack_archive(archive_path, str(tmp_dir))
    except Exception as exc:
        raise RuntimeError(
            f"Failed to extract archive '{archive_path}': {exc}"
        ) from exc

    # Determine which directory contains the repository
    # Prefer a single subdirectory, otherwise use the temp dir itself
    try:
        contents = list(tmp_dir.iterdir())
    except OSError as exc:
        raise RuntimeError(f"Unable to list extracted contents: {exc}") from exc

    if len(contents) == 1 and contents[0].is_dir():
        repo_dir = contents[0]
    else:
        repo_dir = tmp_dir

    # If a desired filename is provided, rename the repo directory accordingly
    if filename:
        desired_path = tmp_dir / filename
        if repo_dir != desired_path:
            try:
                repo_dir.rename(desired_path)
                repo_dir = desired_path
            except OSError as exc:
                raise RuntimeError(
                    f"Could not rename repository directory to '{filename}': {exc}"
                ) from exc

    # Return a file URL to the repository root
    return f"file://{repo_dir.resolve()}"

