def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle None or the special string "always"
    if frequency is None:
        return None
    if not isinstance(frequency, str):
        raise ValueError('frequency must be a string or None')
    freq = frequency.strip().lower()
    if freq == 'always':
        return None
    # Regular expression to capture a numeric value followed by a unit
    import re
    match = re.match(r'^([0-9]+(?:\.[0-9]+)?)\s*([a-zA-Z]+)$', freq)
    if not match:
        raise ValueError(f'Cannot parse frequency: {frequency!r}')
    value_str, unit = match.groups()
    try:
        value = float(value_str)
    except ValueError:
        raise ValueError(f'Invalid numeric value in frequency: {frequency!r}')
    unit = unit.lower()
    # Map the unit to a datetime.timedelta argument
    if unit in ('second', 'seconds'):
        return datetime.timedelta(seconds=value)
    if unit in ('minute', 'minutes'):
        return datetime.timedelta(minutes=value)
    if unit in ('hour', 'hours'):
        return datetime.timedelta(hours=value)
    if unit in ('day', 'days'):
        return datetime.timedelta(days=value)
    if unit in ('week', 'weeks'):
        return datetime.timedelta(weeks=value)
    if unit in ('month', 'months'):
        return datetime.timedelta(days=30 * value)
    if unit in ('year', 'years'):
        return datetime.timedelta(days=365 * value)
    raise ValueError(f'Unknown time unit in frequency: {frequency!r}')

