def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    host = host.strip()

    # Short circuit common names
    if host == "localhost":
        return True

    try:
        # Resolve host to addresses; the port is irrelevant, so None
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            addr = sockaddr[0]
            if family == socket.AF_INET:
                # IPv4 loopback starts with 127.
                if addr.split(".", 1)[0] == "127":
                    return True
            elif family == socket.AF_INET6:
                # IPv6 loopback is ::1
                if addr.lower() in ("::1", "0:0:0:0:0:0:0:1"):
                    return True
    except socket.gaierror:
        # If resolution fails, host is not recognized as localhost
        return False
    except Exception:
        # Catch-all for unforeseen issues; conservatively treat as not local
        return False

    return False

