def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    # Determine the appropriate compiled pattern type for the current Python version
    try:
        PatternType = re.Pattern
    except AttributeError:
        PatternType = re._pattern_type

    # If the input is already a compiled regex, return it unchanged
    if isinstance(pattern, PatternType):
        return pattern

    # If the input is a string, optionally strip whitespace and compile
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)

    # For any other type, raise a clear TypeError
    raise TypeError(f"Invalid pattern type: {type(pattern).__name__}")

