def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed
    configuration, and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import logging
    try:
        import yaml
    except ImportError:
        yaml = None
    try:
        import toml
    except ImportError:
        toml = None
    import re

    parsed = {}
    error_records = []

    def _record_error(filename, error_msg, exception=None):
        """Create a LogRecord for an error."""
        record = logging.LogRecord(
            name='load_configurations',
            level=logging.ERROR,
            pathname=filename,
            lineno=0,
            msg=error_msg,
            args=(),
            exc_info=exception
        )
        error_records.append(record)

    def _resolve_env_vars(value):
        """Recursively resolve ${VAR} placeholders in strings."""
        if isinstance(value, str):
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                var_name = match.group(1)
                return os.getenv(var_name, match.group(0))
            return pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _resolve_env_vars(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env_vars(v) for v in value]
        return value

    if isinstance(config_filenames, str):
        config_filenames = [config_filenames]

    for fname in config_filenames:
        if not os.path.isfile(fname):
            _record_error(fname, f"File does not exist or is not a file: {fname}")
            continue
        try:
            with open(fname, 'r', encoding='utf-8') as fh:
                raw = fh.read()
        except Exception as exc:
            _record_error(fname, f"Failed to read file: {fname}", exc_info=exc)
            continue

        config = None
        ext = os.path.splitext(fname)[1].lower()

        try:
            if ext == '.json':
                config = json.loads(raw)
            elif ext in ('.yaml', '.yml'):
                if yaml is None:
                    raise ImportError("PyYAML is not installed")
                config = yaml.safe_load(raw)
            elif ext == '.toml':
                if toml is None:
                    raise ImportError("toml is not installed")
                config = toml.loads(raw)
            else:
                _record_error(fname, f"Unsupported file extension: {ext}")
                continue
        except Exception as exc:
            _record_error(fname,
                          f"Failed to parse configuration file: {fname}",
                          exc_info=exc)
            continue

        # Validate: ensure parsed config is a dictionary
        if not isinstance(config, dict):
            _record_error(fname,
                          f"Configuration file did not return a dictionary: {fname}")
            continue

        # Apply environment variable resolution if requested
        if resolve_env:
            config = _resolve_env_vars(config)

        # Apply overrides if provided
        if isinstance(overrides, dict):
            config.update(overrides)

        parsed[fname] = config

    return parsed, error_records

