def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute the integral of the histogram
    def _compute_scale():
        if not hasattr(self, 'histogram'):
            raise AttributeError("Histogram object has no 'histogram' attribute")
        h = self.histogram
        if not hasattr(self, 'axes'):
            raise AttributeError("Histogram object has no 'axes' attribute")
        ndim = h.ndim
        # Start with volumes array of ones
        volumes = 1.0
        for i, axis in enumerate(self.axes):
            try:
                edges = axis.bin_edges
            except AttributeError:
                raise AttributeError("Axis object has no 'bin_edges' attribute")
            widths = np.diff(edges)
            # Reshape widths to broadcast along each axis
            reshape = [1] * ndim
            reshape[i] = -1
            volumes = volumes * widths.reshape(reshape)
        return np.sum(h * volumes)

    # If we are just querying the scale
    if other is None:
        if getattr(self, '_scale_computed', False) and not recompute:
            return getattr(self, '_scale', 0.0)
        try:
            scale_val = _compute_scale()
        except Exception as e:
            raise RuntimeError(f"Failed to compute histogram scale: {e}")
        self._scale = scale_val
        self._scale_computed = True
        return scale_val

    # Otherwise, we are asked to set the scale to a new value
    if not isinstance(other, (int, float)):
        raise TypeError("`other` must be a float or int representing the new scale")

    try:
        current_scale = _compute_scale() if recompute or not getattr(self, '_scale_computed', False) else getattr(self, '_scale', 0.0)
    except Exception as e:
        raise RuntimeError(f"Failed to compute current histogram scale: {e}")

    if current_scale == 0:
        raise ValueError("Histograms with scale equal to zero cannot be rescaled")

    factor = other / current_scale
    if hasattr(self, 'histogram'):
        self.histogram = self.histogram * factor
    else:
        raise AttributeError("Histogram object has no 'histogram' attribute to rescale")
    # Store the new scale and mark it as computed
    self._scale = other
    self._scale_computed = True
    return other

