def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Import numeric helper and math for NaN checks
    import numbers
    import math

    # Determine the internal scale attribute name
    internal_scale_attr = "_scale"
    if not hasattr(self, internal_scale_attr):
        # Fallback to a public attribute named 'scale'
        internal_scale_attr = "scale"
    current_scale = getattr(self, internal_scale_attr, None)

    if other is None:
        # Return the current scale value
        return current_scale

    # Validate the new scale
    if not isinstance(other, numbers.Real):
        raise TypeError(f"Scale must be a real number, got {type(other).__name__}")

    # Check for unknown or zero current scale
    if current_scale is None:
        raise LenaValueError("Cannot rescale: graph has unknown scale.")
    if isinstance(current_scale, float) and math.isnan(current_scale):
        raise LenaValueError("Cannot rescale: graph has NaN scale.")
    if current_scale == 0:
        raise LenaValueError("Cannot rescale: graph has zero scale.")

    # Determine the last coordinate to rescale
    last_coord = None
    if hasattr(self, "coordinates") and isinstance(self.coordinates, (list, tuple)) and self.coordinates:
        last_coord = self.coordinates[-1]
    elif hasattr(self, "fields") and isinstance(self.fields, (list, tuple)) and self.fields:
        # In some implementations fields might be a list of tuples (name, data)
        # or a dict; handle common patterns
        if isinstance(self.fields, dict):
            last_coord = list(self.fields.keys())[-1]
        else:
            last_coord = self.fields[-1]
    else:
        raise AttributeError("Graph has no coordinate fields to rescale.")

    # Compute scaling factor
    factor = other / current_scale

    # Rescale the coordinate data
    try:
        # For dict-like fields
        if hasattr(self, "fields"):
            if isinstance(self.fields, dict) and last_coord in self.fields:
                self.fields[last_coord] = self.fields[last_coord] * factor
            elif isinstance(self.fields, (list, tuple)):
                # Assume list of (name, array) pairs
                for i, (name, arr) in enumerate(self.fields):
                    if name == last_coord:
                        self.fields[i] = (name, arr * factor)
            else:
                # Other structures are unsupported
                raise TypeError("Unsupported fields structure.")
    except Exception as exc:
        raise RuntimeError(f"Failed to rescale coordinate '{last_coord}': {exc}") from exc

    # Rescale corresponding errors if present
    if hasattr(self, "errors"):
        try:
            if isinstance(self.errors, dict) and last_coord in self.errors:
                self.errors[last_coord] = self.errors[last_coord] * factor
            elif isinstance(self.errors, (list, tuple)):
                for i, (name, arr) in enumerate(self.errors):
                    if name == last_coord:
                        self.errors[i] = (name, arr * factor)
        except Exception:
            # Errors are optional; ignore failures silently
            pass

    # Update the graph's scale
    setattr(self, internal_scale_attr, other)    
    return None

