def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Basic validation
    if get_coordinate not in {"left", "right", "middle"}:
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")

    if not isinstance(field_names, (list, tuple)):
        raise TypeError("field_names must be a sequence of names")

    # Determine the scale to use
    if scale is True:
        try:
            scale = getattr(hist, "scale", None)
        except Exception:
            scale = None

    # Helper to extract bin coordinate
    def _coordinate(bin_obj):
        left = getattr(bin_obj, "left", None)
        if left is None:
            left = getattr(bin_obj, "left_edge", None)
        right = getattr(bin_obj, "right", None)
        if right is None:
            right = getattr(bin_obj, "right_edge", None)

        if left is None or right is None:
            raise AttributeError(
                "Histogram bin does not expose left/right edges"
            )
        if get_coordinate == "left":
            return left
        if get_coordinate == "right":
            return right
        return (left + right) / 2.0

    # Helper to get bin content/value
    def _value(bin_obj):
        # Try to get raw content
        try:
            content = getattr(bin_obj, "content")
        except AttributeError:
            try:
                content = getattr(bin_obj, "value")
            except AttributeError:
                content = bin_obj
        if make_value is None:
            return content
        return make_value(content)

    points = []
    for bin_obj in hist:
        try:
            x_coord = _coordinate(bin_obj)
        except Exception as exc:
            raise ValueError(f"Cannot determine coordinate for bin {bin_obj}") from exc

        try:
            val = _value(bin_obj)
        except Exception as exc:
            raise ValueError(f"Cannot extract value from bin {bin_obj}") from exc

        # If val is a scalar but there are multiple field names, raise
        if not hasattr(val, "__iter__") or isinstance(val, (str, bytes)):
            val_items = [val]
        else:
            val_items = list(val)

        if len(val_items) != len(field_names):
            raise ValueError(
                f"Number of values {len(val_items)} does not match number of field_names {len(field_names)}"
            )

        point = dict(zip(field_names, [x_coord] + val_items[1:]) if len(field_names) > 1 else {field_names[0]: x_coord})
        # If first field name is 'x', ensure its value is coordinate
        if field_names[0] == "x":
            point[field_names[0]] = x_coord
        else:
            # In case field_names[0] is something else, keep coordinate as first value
            point[field_names[0]] = x_coord

        # For remaining fields, assign from val_items
        for name, value in zip(field_names[1:], val_items[1:]):
            point[name] = value

        points.append(point)

    # Return graph as a simple list of points; real implementation would construct a graph object
    graph = points
    if scale is not None:
        graph = {"scale": scale, "points": points}
    return graph

