def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        raise ValueError("At least one base class must be provided")

    # If an explicit metaclass was supplied, use it directly
    if explicit_mc is not None:
        # If it is not already a type, attempt to coerce it to a type
        if not isinstance(explicit_mc, type):
            try:
                explicit_mc = type(explicit_mc)
            except Exception as exc:  # pragma: no cover
                raise TypeError("explicit_mc must be a metaclass (type)") from exc
        return explicit_mc

    # Derive the metaclass from the given bases
    try:
        metaclasses = [type(b) for b in bases]
    except Exception as exc:
        raise TypeError("All bases must be valid class objects") from exc

    # Find the most derived metaclass among those of the bases
    for candidate in metaclasses:
        if all(issubclass(candidate, mc) for mc in metaclasses):
            return candidate

    # Fallback: use the metaclass of the first base
    # This handles cases where no single metaclass dominates
    return type(bases[0])

