def fetch_content_type(url: str):
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    # Validate input
    if not isinstance(url, str) or not url:
        return None

    # Only handle HTTP(S) URLs
    try:
        parsed = urlparse(url)
    except Exception:
        return None
    if parsed.scheme not in ("http", "https"):
        return None

    # Construct HEAD request
    try:
        req = Request(url, method="HEAD")
        # Optional: set a User-Agent
        req.add_header("User-Agent", "fetch-content-type/1.0")
        with urlopen(req, timeout=10) as resp:
            # Some servers may return non‑200 status; ignore them
            try:
                status = resp.getcode()
            except AttributeError:
                status = getattr(resp, "status", None)
            if status is not None and (status < 200 or status >= 400):
                return None
            return resp.info().get("content-type")
    except (Exception, OSError):
        return None

# Note: This function returns `None` when the content type cannot be determined.
# It relies on urllib.request and urllib.parse being imported elsewhere.

