def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversion – child nodes are not recursively processed.
    Child elements that share the same tag name are stored as a list under that key.
    Namespace prefixes are stripped from tags.
    """
    if node is None:
        raise ValueError("node cannot be None")

    result = {}
    try:
        child_iter = iter(node)
    except TypeError:
        raise TypeError("Expected an ElementTree element with iterable children")

    for child in child_iter:
        tag = child.tag
        if isinstance(tag, str) and tag.startswith('{'):
            # Strip namespace
            tag = tag.split('}', 1)[1]
        if tag not in result:
            result[tag] = child
        else:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
    return result

