def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET
    result: Dict[str, object] = {}
    if not document:
        return result
    # Try JSON first
    try:
        data = json.loads(document)
        result = {"subject": data.get("subject")}
        # Extract hcard link
        hcard_url = None
        links = data.get("links", [])
        for link in links:
            # link can be a dict; rel may be string or list
            rel = link.get("rel")
            href = link.get("href")
            if href and rel:
                if isinstance(rel, list):
                    if "hcard" in rel or "http://webfinger.net/rel/hcard" in rel:
                        hcard_url = href
                        break
                else:
                    if rel == "hcard" or rel == "http://webfinger.net/rel/hcard":
                        hcard_url = href
                        break
        result["hcard_url"] = hcard_url
        return result
    except Exception:
        pass  # fall back to XRD parsing

    # Assume XRD
    try:
        root = ET.fromstring(document)
        # XRD namespace handling
        ns = {"xrd": "xrd.info/xrd.xsd", "xrd": "x29"}
        # try to find link with appropriate rel
        for link in root.findall(".//{*}Link"):
            rel = link.attrib.get("rel")
            href = link.attrib.get("href")
            if href and rel:
                if rel == "http://webfinger.net/rel/hcard" or rel == "self":
                    # XRD repos may use different rels; prefer hcard
                    # store the first found
                    result["hcard_url"] = href
                    break
        if "hcard_url" not in result:
            # fallback: look for a <Link> with href and maybe rel omitted
            for link in root.findall(".//{*}Link"):
                href = link.attrib.get("href")
                if href:
                    result["hcard_url"] = href
                    break
        return result
    except Exception:
        # If parsing fails, return empty dict
        return {"hcard_url": None}

