def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    # Resolve settings_dirs to a list
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        dirs = list(settings_dirs or [])
    # Resolve spec_option to a pattern string
    if isinstance(spec_option, (list, tuple)):
        # Join patterns with commas, use fnmatch to match any
        pattern = "*"
        for pat in spec_option:
            pattern = f"{pat}"
            break  # use first pattern (fallback to simple behavior)
    else:
        pattern = spec_option or "*"
    try:
        import os
        import fnmatch
        file_list = []
        for directory in dirs:
            if not directory:
                continue
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                if fnmatch.fnmatch(fname, pattern):
                    file_list.append(os.path.join(directory, fname))
        return sorted(file_list)
    except Exception:
        return []

