            raise TypeError(f"command_name must be a string, got {type(command_name).__name__}")

        # Prefer an attribute that holds all command specifications
        spec_dict = None
        try:
            # Common naming patterns
            if hasattr(self, "_command_specs"):
                spec_dict = getattr(self, "_command_specs")
            elif hasattr(self, "command_specs"):
                spec_dict = getattr(self, "command_specs")
            else:
                raise AttributeError
        except AttributeError:
            raise AttributeError(
                f"{self.__class__.__name__} instance does not provide a command specifications dictionary"
            )

        if not isinstance(spec_dict, dict):
            raise TypeError(
                f"specifications attribute is expected to be a dict, got {type(spec_dict).__name__}"
            )

        try:
