def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    try:
        if args is None:
            return []
        # Ensure we have an iterable of strings
        silent_args = set()
        for arg in args:
            if not isinstance(arg, str):
                continue
            if arg.startswith("--"):
                # Long form: --option or --option=value
                name = arg[2:].split('=', 1)[0]
                if name:
                    silent_args.add(name)
            elif arg.startswith("-") and len(arg) > 1:
                # Short form: -a or grouped -abc
                # If contains '=', split
                if "=" in arg:
                    name = arg[1:].split('=', 1)[0]
                    if name:
                        silent_args.add(name)
                else:
                    # group each char
                    for ch in arg[1:]:
                        if ch:
                            silent_args.add(ch)
        return list(silent_args)
    except Exception:
        # In case of any unexpected issue return empty list
        return []

