def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    # Helper to evaluate a condition expressed in various forms
    def _eval_cond(cond, args, command_name):
        try:
            if callable(cond):
                # Expect arguments: args and command_name
                return bool(cond(args, command_name))
            if isinstance(cond, str):
                # Evaluate string expression with args (if dict) and command_name
                local_vars = {}
                if isinstance(args, dict):
                    local_vars.update(args)
                local_vars['command_name'] = command_name
                return bool(eval(cond, {}, local_vars))
            if isinstance(cond, (list, tuple)) and len(cond) == 2:
                key, value = cond
                if isinstance(args, dict):
                    return args.get(key) == value
                return False
            # Fallback: truthiness of the condition itself
            return bool(cond)
        except Exception:
            # If evaluation fails, treat as not satisfied
            return False

    required = []
    if not isinstance(options_spec, (list, tuple)):
        raise TypeError("options_spec must be a list or tuple of spec dicts")
    for spec in options_spec:
        if not isinstance(spec, dict):
            continue
        cond = spec.get('required_when')
        if cond is None:
            continue
        # Determine the name of the argument to be marked
        # Prefer 'arg', fallback to 'name', and as last resort use keys not starting with '_'
        name = spec.get('arg') or spec.get('name')
        if name is None:
            # Attempt to find a non-metadata key
            for k in spec:
                if not k.startswith('_') and k not in ('required_when', 'flags'):
                    name = k
                    break
        if not name:
            continue
        if _eval_cond(cond, args, command_name):
            required.append(name)
    return required

