def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments (dict mapping names to values).
    :raises TypeError: If ``args`` is not a dict.
    :raises ValueError: If any value falls outside its defined bounds.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a mapping of argument names to values")
    for name, value in args.items():
        # Determine corresponding bounds attributes
        min_attr = f"{name}_min"
        max_attr = f"{name}_max"
        min_value = getattr(self, min_attr, None)
        max_value = getattr(self, max_attr, None)
        # Skip checking if no bounds are specified
        if min_value is None and max_value is None:
            continue
        # Perform comparisons, handling non-comparable types gracefully
        try:
            if min_value is not None and value < min_value:
                raise ValueError(
                    f"Argument '{name}' with value {value} is below minimum {min_value}"
                )
            if max_value is not None and value > max_value:
                raise ValueError(
                    f"Argument '{name}' with value {value} exceeds maximum {max_value}"
                )
        except TypeError as exc:
            raise ValueError(
                f"Cannot compare value of argument '{name}' ({value}) "
                f"with its bounds ({min_value}, {max_value})"
            ) from exc
    return True

