def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    if not path or not root:
        raise ValueError("Path and root must not be empty")
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    # Ensure that root is a prefix of the path
    try:
        # relpath will raise ValueError on disjoint paths (e.g., different drives on Windows)
        rel = os.path.relpath(norm_path, norm_root)
    except ValueError as exc:
        raise ValueError(f"Root '{root}' does not match path '{path}': {exc}") from exc
    # If the relative path is the same as the original, we did not strip anything
    if rel == norm_path:
        if norm_path == norm_root:
            return ''  # root and path are identical
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")
    # If relative path is '.' it means the path is exactly the root
    if rel == '.':
        return ''
    return rel

